import { Product, ProductVariant, Department, ProductCategory, ShoeGender } from '../types';
import { normalizeBrand } from './brandUtils';

// Helper to create variants distributed across sizes with total stock matching legacy stock
function createVariants(
  sku: string,
  dept: Department,
  cat: ProductCategory,
  gender: ShoeGender,
  totalStock: number,
  mainEan: string
): ProductVariant[] {
  const stock = Math.max(0, Math.round(totalStock));
  let sizes: (string | number)[] = [35, 36, 37, 38, 39];

  if (dept === 'Roupas') {
    sizes = ['P', 'M', 'G', 'GG'];
  } else if (gender === 'Infantil') {
    sizes = [26, 27, 28, 29, 30, 31, 32];
  } else if (gender === 'Masculino') {
    sizes = [38, 39, 40, 41, 42, 43];
  } else if (cat === 'Chinelos' || cat === 'Sandália') {
    sizes = [35, 36, 37, 38, 39, 40];
  }

  const basePerSize = Math.floor(stock / sizes.length);
  let remainder = stock % sizes.length;

  return sizes.map((size, idx) => {
    const qty = basePerSize + (remainder > 0 ? 1 : 0);
    if (remainder > 0) remainder--;
    return {
      id: `var_${sku}_${size}`,
      color: 'Padrão',
      colorHex: '#1e293b',
      size,
      stock: qty,
      ean: `${mainEan.slice(0, 10)}${String(idx + 1).padStart(3, '0')}`,
      minStock: 2,
      shelfLocation: `EST-${sku.slice(-3)}`,
    };
  });
}

function makeProduct(
  sku: string,
  ref: string,
  name: string,
  brand: string,
  dept: Department,
  cat: ProductCategory,
  gender: ShoeGender,
  costPrice: number,
  salePrice: number,
  stock: number,
  ncm: string,
  image: string
): Product {
  const mainEan = ref && ref.length >= 7 && !ref.includes('/') ? ref : `789${sku.padStart(10, '0')}`;
  const cost = Number(costPrice.toFixed(2));
  const sale = Number(salePrice.toFixed(2));
  const markup = cost > 0 ? Math.round(((sale - cost) / cost) * 100) : 100;

  return {
    id: `prod_${sku}`,
    sku,
    mainEan,
    name,
    brand: normalizeBrand({ name, brand, model: ref }),
    model: ref || name,
    department: dept,
    category: cat,
    gender,
    collection: '2026',
    material: dept === 'Calçados' ? 'Sintético / Conforto' : 'Têxtil / Algodão',
    costPrice: cost,
    freightExpenses: 0,
    markupPercentage: markup,
    salePrice: sale,
    images: [image],
    variants: createVariants(sku, dept, cat, gender, stock, mainEan),
    fiscalData: {
      ncm: ncm || (dept === 'Calçados' ? '6402.99.90' : '6106.20.00'),
      cest: '',
      origin: '0',
      cfop: '5102',
      csosn: '102',
      icmsRate: 0,
      pisRate: 0,
      cofinsRate: 0,
      nfeKey: '',
      supplierCnpj: '',
    },
    createdAt: '2025-01-15T10:00:00.000Z',
    updatedAt: '2025-01-15T10:00:00.000Z',
  };
}

